theorem SierpinskiRationals.BinaryScheme.code_has_both_bits.{u_1} {X : Type u_1} [TopologicalSpace X] {B : Nat → Set X}
  {E : Nat → X} (S : SierpinskiRationals.BinaryScheme X B E) (hE : Function.Surjective E) (x : X) (N : Nat) (b : Bool) :
  Exists fun n => And (GE.ge n N) (Eq (SierpinskiRationals.BinaryScheme.code S x n) b)

